playlist_song_data = []
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    playlist_details = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
    if 'songs' in playlist_details:
        for song in playlist_details['songs']:
            song_id = song['id']
            song_info = apis.spotify.show_song(song_id=song_id)
            if song_info:
                song_title = song_info['title']
                artists = "|".join([artist['name'] for artist in song_info['artists']])
                playlist_song_data.append({
                    "Title": song_title,
                    "Artists": artists
                })

print(f"Processed {len(playlist_song_data)} songs from playlists")
