content = movie_note['content']
lines = content.split('\n')
movies = []
current_movie = None

for line in lines:
    line = line.strip()
    if not line:
        continue
    if line.startswith('#'):
        continue
    if line.startswith(' - '):
        if current_movie is not None:
            if 'director:' in line:
                director = line.split('director:')[1].strip()
                current_movie['director'] = director
    else:
        if current_movie is not None:
            movies.append(current_movie)
        current_movie = {'title': line, 'director': None}

if current_movie is not None:
    movies.append(current_movie)

peter_jackson_movies = [movie['title'] for movie in movies if movie['director'] and 'Peter Jackson' in movie['director']]
print(peter_jackson_movies)
