content = dinner_note['content']
lines = content.split('\n')
shares = {}
for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('-'):
        # Verify the line has the expected format: starts with '-' and contains '=>'
        if '=>' in line:
            parts = line.split('=>')
            if len(parts) == 2:
                name = parts[0].strip()
                amount_str = parts[1].strip()
                # Extract amount (everything after $)
                if amount_str.startswith('$'):
                    amount = float(amount_str[1:])
                else:
                    amount = float(amount_str)
                shares[name] = amount

print(f"Extracted shares: {shares}")
