content = dinner_note['content']
lines = content.split('\n')
shares = {}
for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('-') and '=>' in line:
        # Extract name and amount
        parts = line.split('=>')
        if len(parts) == 2:
            name = parts[0].strip()[1:].strip()  # Remove the dash and any extra spaces
            amount_str = parts[1].strip()
            # Extract amount (everything after $)
            if amount_str.startswith('$'):
                amount = float(amount_str[1:])
            else:
                amount = float(amount_str)
            shares[name] = amount

print(f"Extracted shares: {shares}")
