    page_result = apis.phone.show_alarms(access_token=phone_access_token, page_index=page_index)
    if not page_result:
        break
    final_alarms.extend(page_result)
    page_index += 1

# Check if wake-up alarm is at 06:50 and all others are disabled
wake_up_updated = None
all_disabled = True

for alarm in final_alarms:
    if alarm['alarm_id'] == wake_up_alarm['alarm_id']:
        wake_up_updated = alarm
        if wake_up_updated['time'] != new_time:
            all_disabled = False
        break

for alarm in final_alarms:
    if alarm['alarm_id'] != wake_up_alarm['alarm_id'] and alarm['enabled'] == True:
        all_disabled = False
        break

if wake_up_updated and wake_up_updated['time'] == new_time and all_disabled:
    apis.supervisor.complete_task()
else:
